3	import net.officefloor.plugin.variable.Out;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.web.bind.annotation.RequestBody;
6	
7	/**
8	 * Normalizes the address of a create request to its canonical form (see
9	 * {@link AddressNormalizer#normalize(String)}) before any other rule runs. Running first means the
10	 * required-field check ({@link ValidateOwnerFields}) rejects an address that is blank after
11	 * normalization, the household comparison ({@link AssignHousehold}) compares normalized addresses,
12	 * and {@link BuildOwner} stores — and later responses return — the
13	 * normalized form. Binds the request body once and republishes it for the rest of the pipeline.
14	 */
15	public class NormalizeAddress {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized) {
18	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
19	        normalized.set(request);
20	    }
21	}
