19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
26	    @Mapping(target = "initials", expression = "java(initials(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /** The owner's name formatted as 'LastName, FirstName'. */
35	    default String displayName(Owner owner) {
36	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
37	    }
38	
39	    /** The canonical region derived from the owner's city (see {@link CityRegion#of(String)}). */
40	    default String locality(Owner owner) {
41	        return owner == null ? null : CityRegion.of(owner.getCity());
42	    }
43	
44	    /** The upper-cased first letters of the first and last name, e.g. 'J.S.'. */
45	    default String initials(Owner owner) {
46	        return owner == null ? null
47	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
48	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
49	    }
50	
51	    /**
52	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
53	     * last two digits of the registration date's year, e.g. 'SYD-SMI-0007-M26'.
54	     */
55	    default String membershipNumber(Owner owner) {
56	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
57	            return null;
58	        }
59	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
60	    }
61	
62	    /**
63	     * The owner's membership level (see {@link MembershipLevel}): a number from 1 to 3 that starts
64	     * at 1, gains 1 for a present email address and 1 for a unique name (namesakeCount is zero),
65	     * capped at 3.
66	     */
67	    default Integer membershipLevel(Owner owner) {
68	        return MembershipLevel.of(owner);
69	    }
70	
71	    /**
72	     * The owner's preferred contact channel (see {@link ContactPreference}): 'EMAIL' when an email
73	     * address is present, otherwise 'PHONE'.
74	     */
75	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
76	        ContactPreference preference = ContactPreference.of(owner);
77	        return preference == null ? null : OwnerDto.ContactPreferenceEnum.valueOf(preference.name());
78	    }
79	
80	    /**
81	     * The owner's derived identity key (see {@link IdentityKey}): the canonical telephone, email and
82	     * household id joined by '|'. The single value duplicate detection consolidates on.
83	     */
84	    default String identityKey(Owner owner) {
85	        return owner == null ? null : IdentityKey.forOwner(owner);
86	    }
87	
88	    Owner toOwner(OwnerDto ownerDto);
89	
90	    @Mapping(target = "id", ignore = true)
91	    @Mapping(target = "pets", ignore = true)
92	    Owner toOwner(OwnerFieldsDto ownerDto);
93	
94	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
95	
96	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
97	
98	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
99	        OwnerPageDto ownerPageDto = new OwnerPageDto();
100	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
101	        ownerPageDto.setPage(ownerPage.getNumber());
102	        ownerPageDto.setSize(ownerPage.getSize());
103	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
104	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
105	        return ownerPageDto;
106	    }
107	}
